using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using UnityEngine;

namespace ABRevival.Core.Data
{
    /// <summary>
    /// Deterministic, inspectable snapshot of one decoded level record.
    /// Generated by the level data importer; never authored by hand.
    /// Original game IP: Vargames (2011).
    /// </summary>
    [CreateAssetMenu(fileName = "NewLevelDefinition", menuName = "ABRevival/Level Definition")]
    public class LevelDefinitionSO : ScriptableObject
    {
        [Serializable]
        public sealed class EventEntry
        {
            public string name;
            public string after;
            public bool timed;
            public int timeTicks;
            public string trigger;
            public string acts;
        }

        public int storyKey;
        public int storyIndex;
        public string background;
        public float cameraWidth;
        public float cameraHeight;
        public int eventCount;
        public int spawnCount;
        public int talkHookCount;
        public string levelTalk;
        public List<EventEntry> events = new List<EventEntry>();

        public void Populate(LevelRecord level)
        {
            storyKey = level.storyKey;
            storyIndex = level.StoryIndex;
            background = level.background;
            cameraWidth = level.cameraWidth;
            cameraHeight = level.cameraHeight;
            eventCount = level.events.Count;
            spawnCount = level.spawns.Count;
            levelTalk = FormatTalk(level.talk);

            events.Clear();
            int talkHooks = level.talk != null ? 1 : 0;
            for (int i = 0; i < level.initialActs.Count; i++)
                if (level.initialActs[i].talk != null) talkHooks++;
            for (int i = 0; i < level.events.Count; i++)
            {
                var ev = level.events[i];
                var acts = new StringBuilder();
                for (int a = 0; a < ev.finishActs.Count; a++)
                {
                    if (acts.Length > 0) acts.Append(", ");
                    acts.Append(FormatAct(ev.finishActs[a]));
                    if (ev.finishActs[a].talk != null) talkHooks++;
                }
                for (int a = 0; a < ev.frameActs.Count; a++)
                {
                    if (acts.Length > 0) acts.Append(", ");
                    acts.Append("frame:").Append(FormatAct(ev.frameActs[a].act))
                        .Append('@').Append(ev.frameActs[a].interval);
                    if (ev.frameActs[a].act != null && ev.frameActs[a].act.talk != null) talkHooks++;
                }

                events.Add(new EventEntry
                {
                    name = ev.name,
                    after = ev.after,
                    timed = ev.isTimed,
                    timeTicks = ev.timeTicks,
                    trigger = FormatTrigger(ev),
                    acts = acts.ToString()
                });
            }
            talkHookCount = talkHooks;
        }

        private static string FormatTrigger(LevelEvent ev)
        {
            if (ev.place != null)
                return string.Format(CultureInfo.InvariantCulture, "place:{0}@{1},{2},{3},{4}",
                    ev.place.pilot, ev.place.x, ev.place.y, ev.place.width, ev.place.height);
            if (ev.death != null)
                return string.Format(CultureInfo.InvariantCulture, "death:{0}/{1}",
                    ev.death.targetPilot ?? "all", ev.death.requiredKills);
            if (ev.finishKind == LevelFinishKind.Win) return "win:no-hostiles";
            if (ev.finishKind == LevelFinishKind.Win1) return "win:one-hostile";
            return string.Empty;
        }

        private static string FormatTalk(LevelTalkHook hook)
        {
            return hook == null
                ? string.Empty
                : string.Format(CultureInfo.InvariantCulture, "{0}-{1}", hook.firstLine, hook.lastLine);
        }

        private static string FormatAct(LevelAct act)
        {
            if (act == null) return string.Empty;
            if (act.spawn == null) return act.talk != null
                ? string.Format(CultureInfo.InvariantCulture, "talk:{0}-{1}", act.talk.firstLine, act.talk.lastLine)
                : act.name;

            var spawn = act.spawn;
            return string.Format(CultureInfo.InvariantCulture, "{0}:{1}@{2},{3}",
                spawn.kind, spawn.pilot, spawn.x, spawn.y);
        }
    }
}
